/**
 * src/data/waiyansheSL.ts
 *
 * 外研版一年级起点：小学 1-6 年级《英语（新标准）一起》+ 初中 7-9 年级外研版
 *
 * 数据来源：教材官方目录（dzkbw 电子课本网，教材原页）核对单元结构，
 * 词条取自教材单词表（含音标与中文释义），多义词保留全部义项。
 * 重建日期：2026-09-11（第三次重建，全部替换为按官方教材逐册录入的真实数据）
 *
 * grade = 真实年级（1-9），unit = 年级内连续编号（上册在前，下册续接）。
 */
import { mk } from "./mk";
import type { UnitInfo, WordEntry } from "./curriculum";

function w(
  grade: number,
  unit: number,
  english: string,
  phonetic: string,
  chinese: string
): WordEntry {
  return mk(grade, unit, "word", english, phonetic, chinese);
}

